// Python-style repr()/str() rendering for the JSON value model used here:
//   null -> None, boolean -> True/False, string -> str,
//   BigInt -> Python int, Number -> Python float,
//   Array -> list, Map -> dict (insertion order preserved).

// Code points Python's str.isprintable() treats as non-printable.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Zl}\p{Zp}\p{Zs}]/u;

// repr() of a Python float: shortest round-trip digits, fixed notation when
// -4 <= decimal exponent < 16, scientific notation otherwise.
export function reprFloat(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  let neg = false;
  if (x < 0 || Object.is(x, -0)) { neg = true; x = -x; }
  if (x === 0) return neg ? '-0.0' : '0.0';

  const s = x.toString(); // JS shortest round-trip representation
  let digits, e;
  const sci = s.match(/^(\d)(?:\.(\d+))?[eE]([+-]?\d+)$/);
  if (sci) {
    digits = sci[1] + (sci[2] || '');
    e = parseInt(sci[3], 10);
  } else if (s.includes('.')) {
    const dot = s.indexOf('.');
    const ip = s.slice(0, dot);
    const fp = s.slice(dot + 1);
    if (ip !== '0') {
      digits = ip + fp;
      e = ip.length - 1;
    } else {
      const zeros = fp.match(/^0*/)[0].length;
      digits = fp.slice(zeros);
      e = -(zeros + 1);
    }
  } else {
    digits = s;
    e = s.length - 1;
  }
  digits = digits.replace(/0+$/, '') || '0';

  let out;
  if (e < -4 || e >= 16) {
    const mant = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const esign = e < 0 ? '-' : '+';
    const eabs = String(Math.abs(e)).padStart(2, '0');
    out = `${mant}e${esign}${eabs}`;
  } else if (e >= 0) {
    if (digits.length > e + 1) {
      out = digits.slice(0, e + 1) + '.' + digits.slice(e + 1);
    } else {
      out = digits.padEnd(e + 1, '0') + '.0';
    }
  } else {
    out = '0.' + '0'.repeat(-e - 1) + digits;
  }
  return neg ? '-' + out : out;
}

// repr() of a Python str.
export function reprStr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x20 || NON_PRINTABLE.test(ch)) {
      if (cp <= 0xff) out += '\\x' + cp.toString(16).padStart(2, '0');
      else if (cp <= 0xffff) out += '\\u' + cp.toString(16).padStart(4, '0');
      else out += '\\U' + cp.toString(16).padStart(8, '0');
    } else {
      out += ch;
    }
  }
  return out + quote;
}

// repr() of an arbitrary value.
export function reprValue(v) {
  if (v === null) return 'None';
  if (v === true) return 'True';
  if (v === false) return 'False';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'number') return reprFloat(v);
  if (typeof v === 'string') return reprStr(v);
  if (Array.isArray(v)) return '[' + v.map(reprValue).join(', ') + ']';
  if (v instanceof Map) {
    return '{' + [...v].map(([k, val]) => reprStr(k) + ': ' + reprValue(val)).join(', ') + '}';
  }
  return String(v);
}

// str() of a Python number (used in several validation messages).
export function numToStr(v) {
  return typeof v === 'bigint' ? v.toString() : reprFloat(v);
}

// Faithful reimplementation of Python's json.loads() (strict mode):
// - integers parse to BigInt (arbitrary precision, like Python int)
// - floats parse to Number
// - objects parse to Map (insertion order kept, duplicate keys: last wins,
//   position kept -- exactly like a Python dict)
// - NaN / Infinity / -Infinity literals are accepted
// - error messages match json.decoder.JSONDecodeError wording and positions

export class JSONDecodeError extends Error {
  constructor(msg, doc, pos) {
    const line = doc.slice(0, pos).split('\n').length;
    const nl = doc.lastIndexOf('\n', pos - 1);
    const col = pos - nl; // nl is -1 when absent -> col = pos + 1
    super(`${msg}: line ${line} column ${col} (char ${pos})`);
    this.name = 'JSONDecodeError';
    this.msg = msg;
    this.pos = pos;
    this.lineno = line;
    this.colno = col;
  }
}

export function jsonLoads(doc) {
  let pos = 0;
  const fail = (msg, at = pos) => { throw new JSONDecodeError(msg, doc, at); };
  const skipWs = () => {
    while (pos < doc.length && (doc[pos] === ' ' || doc[pos] === '\t' || doc[pos] === '\n' || doc[pos] === '\r')) pos++;
  };

  function parseString() {
    const start = pos;
    pos++; // opening quote
    let out = '';
    while (pos < doc.length) {
      const ch = doc[pos];
      const cp = doc.codePointAt(pos);
      if (ch === '"') { pos++; return out; }
      if (ch === '\\') {
        const escPos = pos;
        pos++;
        if (pos >= doc.length) break;
        const e = doc[pos];
        switch (e) {
          case '"': out += '"'; pos++; break;
          case '\\': out += '\\'; pos++; break;
          case '/': out += '/'; pos++; break;
          case 'b': out += '\b'; pos++; break;
          case 'f': out += '\f'; pos++; break;
          case 'n': out += '\n'; pos++; break;
          case 'r': out += '\r'; pos++; break;
          case 't': out += '\t'; pos++; break;
          case 'u': {
            const hex = doc.slice(pos + 1, pos + 5);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) fail('Invalid \\uXXXX escape', escPos);
            const unit = parseInt(hex, 16);
            pos += 5;
            // surrogate pair handling (Python accepts lone surrogates; JS strings can too)
            if (unit >= 0xd800 && unit <= 0xdbff && doc.slice(pos, pos + 2) === '\\u') {
              const hex2 = doc.slice(pos + 2, pos + 6);
              if (/^[0-9a-fA-F]{4}$/.test(hex2)) {
                const unit2 = parseInt(hex2, 16);
                if (unit2 >= 0xdc00 && unit2 <= 0xdfff) {
                  out += String.fromCharCode(unit, unit2);
                  pos += 6;
                  break;
                }
              }
            }
            out += String.fromCharCode(unit);
            break;
          }
          default:
            fail('Invalid \\escape', escPos);
        }
        continue;
      }
      if (cp < 0x20) fail('Invalid control character at', pos);
      out += ch;
      pos += ch.length; // advance by UTF-16 units (2 for astral chars)
    }
    fail('Unterminated string starting at', start);
  }

  function parseNumber() {
    const rest = doc.slice(pos);
    const m = rest.match(/^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?/);
    if (!m) fail('Expecting value');
    const tok = m[0];
    pos += tok.length;
    if (/\./.test(tok) || /[eE]/.test(tok)) return Number(tok);
    return BigInt(tok);
  }

  function parseValue() {
    if (pos >= doc.length) fail('Expecting value');
    const ch = doc[pos];
    if (ch === '{') return parseObject();
    if (ch === '[') return parseArray();
    if (ch === '"') return parseString();
    if (ch === '-' || (ch >= '0' && ch <= '9')) {
      if (doc.startsWith('-Infinity', pos)) { pos += 9; return -Infinity; }
      return parseNumber();
    }
    if (doc.startsWith('true', pos)) { pos += 4; return true; }
    if (doc.startsWith('false', pos)) { pos += 5; return false; }
    if (doc.startsWith('null', pos)) { pos += 4; return null; }
    if (doc.startsWith('NaN', pos)) { pos += 3; return NaN; }
    if (doc.startsWith('Infinity', pos)) { pos += 8; return Infinity; }
    fail('Expecting value');
  }

  function parseObject() {
    const obj = new Map();
    pos++; // {
    skipWs();
    if (doc[pos] === '}') { pos++; return obj; }
    for (;;) {
      skipWs();
      if (doc[pos] !== '"') fail('Expecting property name enclosed in double quotes');
      const key = parseString();
      skipWs();
      if (doc[pos] !== ':') fail("Expecting ':' delimiter");
      pos++;
      skipWs();
      const value = parseValue();
      obj.set(key, value); // Map keeps first-insertion position on re-set, like dict
      skipWs();
      if (doc[pos] === ',') { pos++; continue; }
      if (doc[pos] === '}') { pos++; return obj; }
      fail("Expecting ',' delimiter");
    }
  }

  function parseArray() {
    const arr = [];
    pos++; // [
    skipWs();
    if (doc[pos] === ']') { pos++; return arr; }
    for (;;) {
      skipWs();
      arr.push(parseValue());
      skipWs();
      if (doc[pos] === ',') { pos++; continue; }
      if (doc[pos] === ']') { pos++; return arr; }
      fail("Expecting ',' delimiter");
    }
  }

  skipWs();
  const value = parseValue();
  skipWs();
  if (pos < doc.length) fail('Extra data');
  return value;
}

// Python-flavored operations over the JSON value model:
// equality, numeric comparison, and jsonschema type checks.

export function isNumber(v) {
  return typeof v === 'number' || typeof v === 'bigint';
}

// jsonschema's "integer" type: ints and floats with integral values, never booleans.
export function isIntegerType(v) {
  return typeof v === 'bigint' || (typeof v === 'number' && Number.isInteger(v));
}

export function isType(v, t) {
  switch (t) {
    case 'null': return v === null;
    case 'boolean': return typeof v === 'boolean';
    case 'string': return typeof v === 'string';
    case 'array': return Array.isArray(v);
    case 'object': return v instanceof Map;
    case 'number': return isNumber(v);
    case 'integer': return isIntegerType(v);
    default: return false;
  }
}

function bigToNumber(b) {
  // exact below 2**53; good enough above (huge-int vs float comparisons are
  // precision edge cases)
  return Number(b);
}

function numEq(a, b) {
  if (typeof a === 'bigint' && typeof b === 'bigint') return a === b;
  const x = typeof a === 'bigint' ? bigToNumber(a) : a;
  const y = typeof b === 'bigint' ? bigToNumber(b) : b;
  return x === y; // NaN never equals anything, as in Python
}

// Structural equality with jsonschema semantics: ints and floats unify by
// numeric value, booleans are always distinct from numbers.
export function pyEqual(a, b) {
  if (isNumber(a) || isNumber(b)) {
    if (!isNumber(a) || !isNumber(b)) return false;
    return numEq(a, b);
  }
  if (a === null || b === null) return a === b;
  if (typeof a === 'boolean' || typeof b === 'boolean') return a === b;
  if (typeof a === 'string' || typeof b === 'string') return a === b;
  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!pyEqual(a[i], b[i])) return false;
    return true;
  }
  if (a instanceof Map) {
    if (!(b instanceof Map) || a.size !== b.size) return false;
    for (const [k, v] of a) {
      if (!b.has(k) || !pyEqual(v, b.get(k))) return false;
    }
    return true;
  }
  return false;
}

// Three-way numeric comparison; returns NaN if either side is NaN
// (every Python comparison against nan is False).
export function numCompare(a, b) {
  if (typeof a === 'bigint' && typeof b === 'bigint') return a < b ? -1 : a > b ? 1 : 0;
  const x = typeof a === 'bigint' ? bigToNumber(a) : a;
  const y = typeof b === 'bigint' ? bigToNumber(b) : b;
  if (Number.isNaN(x) || Number.isNaN(y)) return NaN;
  return x < y ? -1 : x > y ? 1 : 0;
}

// len() of a Python str = Unicode code points.
export function strLen(s) {
  let n = 0;
  for (const _ of s) n++;
  return n;
}

// Keyword validators mirroring Python jsonschema's behavior and exact
// error message wording. Each validator is a generator yielding
// { message, validator, path, context } objects.
//
// The `api` object is supplied by validator.mjs and provides:
//   api.descend(instance, subschema, path, subPath) -> generator of errors
//   api.isValid(subschema, instance) -> boolean
//   api.getRegex(pattern) -> RegExp (search semantics, like re.search)
//   api.resolveRef(ref) -> subschema
//   api.findEvaluatedPropertyKeys(instance, schema) -> Set<string>
//   api.findEvaluatedItemIndexes(instance, schema) -> Set<number>

import { reprValue, reprStr, numToStr } from './pyrepr.mjs';
import { pyEqual, numCompare, isType, isNumber, strLen } from './pyops.mjs';

function err(message, validator, path, context = []) {
  return { message, validator, path, context };
}

function extrasMsg(extras) {
  // mirrors jsonschema._utils.extras_msg (values in given order)
  const verb = extras.length === 1 ? 'was' : 'were';
  return [extras.map(reprValue).join(', '), verb];
}

// ---------- generic ----------

export function* type(v, instance, schema, path, api) {
  const types = typeof v === 'string' ? [v] : v;
  for (const t of types) if (isType(instance, t)) return;
  const reprs = types.map(reprStr).join(', ');
  yield err(`${reprValue(instance)} is not of type ${reprs}`, 'type', path);
}

export function* enum_(v, instance, schema, path, api) {
  for (const each of v) if (pyEqual(instance, each)) return;
  yield err(`${reprValue(instance)} is not one of ${reprValue(v)}`, 'enum', path);
}

export function* const_(v, instance, schema, path, api) {
  if (!pyEqual(instance, v)) {
    yield err(`${reprValue(v)} was expected`, 'const', path);
  }
}

// ---------- object ----------

export function* required(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  for (const property of v) {
    if (!instance.has(property)) {
      yield err(`${reprStr(property)} is a required property`, 'required', path);
    }
  }
}

export function* properties(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  for (const [property, subschema] of v) {
    if (instance.has(property)) {
      yield* api.descend(instance.get(property), subschema, path, [property]);
    }
  }
}

export function* patternProperties(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  for (const [pattern, subschema] of v) {
    const re = api.getRegex(pattern);
    for (const [k, val] of instance) {
      if (re.test(k)) {
        yield* api.descend(val, subschema, path, [k]);
      }
    }
  }
}

function findAdditionalProperties(instance, schema) {
  const props = schema.get('properties');
  const pp = schema.get('patternProperties');
  let re = null;
  if (pp instanceof Map && pp.size) {
    re = apiRegexUnion([...pp.keys()]);
  }
  const extras = [];
  for (const k of instance.keys()) {
    if (props instanceof Map && props.has(k)) continue;
    if (re && re.test(k)) continue;
    extras.push(k);
  }
  return extras;
}

// late-bound to api.getRegex via closure in makeKeywords
let apiRegexUnion = null;

export function* additionalProperties(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  apiRegexUnion = (pats) => api.getRegex(pats.join('|'));
  const extras = findAdditionalProperties(instance, schema);

  if (v instanceof Map) {
    for (const extra of [...extras].sort()) {
      yield* api.descend(instance.get(extra), v, path, [extra]);
    }
  } else if (v === false && extras.length) {
    const pp = schema.get('patternProperties');
    const patterns = pp instanceof Map ? [...pp.keys()].sort().join('|') : '';
    const sorted = [...extras].sort();
    const verb = sorted.length === 1 ? 'was' : 'were';
    let message;
    if (patterns) {
      if (sorted.length === 1) {
        message = `${reprStr(sorted[0])} does not match any of the regexes: ${reprStr(patterns)}`;
      } else {
        message = `${sorted.map(reprStr).join(', ')} do not match any of the regexes: ${reprStr(patterns)}`;
      }
    } else {
      message = `Additional properties are not allowed (${sorted.map(reprStr).join(', ')} ${verb} unexpected)`;
    }
    yield err(message, 'additionalProperties', path);
  }
}

export function* minProperties(v, instance, schema, path, api) {
  if (!(instance instanceof Map) || instance.size >= v) return;
  const message = numCompare(v, 1n) === 0
    ? `${reprValue(instance)} should be non-empty`
    : `${reprValue(instance)} does not have enough properties`;
  yield err(message, 'minProperties', path);
}

export function* maxProperties(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  if (numCompare(instance.size, v) > 0) {
    yield err(`${reprValue(instance)} has too many properties`, 'maxProperties', path);
  }
}

export function* dependentRequired(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  for (const [property, dependencies] of v) {
    if (!instance.has(property)) continue;
    for (const dependency of dependencies) {
      if (!instance.has(dependency)) {
        yield err(`${reprStr(dependency)} is a dependency of ${reprStr(property)}`, 'dependentRequired', path);
      }
    }
  }
}

export function* dependentSchemas(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  for (const [property, subschema] of v) {
    if (instance.has(property)) {
      yield* api.descend(instance, subschema, path, []);
    }
  }
}

// draft-04/06/07 "dependencies": array form behaves like dependentRequired,
// schema form like dependentSchemas.
export function* dependencies(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  for (const [property, dependency] of v) {
    if (!instance.has(property)) continue;
    if (Array.isArray(dependency)) {
      for (const each of dependency) {
        if (!instance.has(each)) {
          yield err(`${reprStr(each)} is a dependency of ${reprStr(property)}`, 'dependencies', path);
        }
      }
    } else {
      yield* api.descend(instance, dependency, path, []);
    }
  }
}

export function* propertyNames(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  for (const property of instance.keys()) {
    yield* api.descend(property, v, path, []);
  }
}

// ---------- string ----------

export function* minLength(v, instance, schema, path, api) {
  if (typeof instance !== 'string') return;
  if (numCompare(strLen(instance), v) < 0) {
    const message = numCompare(v, 1n) === 0
      ? `${reprStr(instance)} should be non-empty`
      : `${reprStr(instance)} is too short`;
    yield err(message, 'minLength', path);
  }
}

export function* maxLength(v, instance, schema, path, api) {
  if (typeof instance !== 'string') return;
  if (numCompare(strLen(instance), v) > 0) {
    yield err(`${reprStr(instance)} is too long`, 'maxLength', path);
  }
}

export function* pattern(v, instance, schema, path, api) {
  if (typeof instance !== 'string') return;
  if (!api.getRegex(v).test(instance)) {
    yield err(`${reprStr(instance)} does not match ${reprStr(v)}`, 'pattern', path);
  }
}

// ---------- number ----------

export function* minimum(v, instance, schema, path, api) {
  if (!isNumber(instance)) return;
  if (numCompare(instance, v) < 0) {
    yield err(`${reprValue(instance)} is less than the minimum of ${numToStr(v)}`, 'minimum', path);
  }
}

export function* maximum(v, instance, schema, path, api) {
  if (!isNumber(instance)) return;
  if (numCompare(instance, v) > 0) {
    yield err(`${reprValue(instance)} is greater than the maximum of ${numToStr(v)}`, 'maximum', path);
  }
}

// draft-06+ numeric form
export function* exclusiveMinimum(v, instance, schema, path, api) {
  if (!isNumber(instance)) return;
  if (numCompare(instance, v) <= 0) {
    yield err(`${reprValue(instance)} is less than or equal to the minimum of ${numToStr(v)}`, 'exclusiveMinimum', path);
  }
}

export function* exclusiveMaximum(v, instance, schema, path, api) {
  if (!isNumber(instance)) return;
  if (numCompare(instance, v) >= 0) {
    yield err(`${reprValue(instance)} is greater than or equal to the maximum of ${numToStr(v)}`, 'exclusiveMaximum', path);
  }
}

// draft-04 boolean-modifier form
export function* minimumDraft4(v, instance, schema, path, api) {
  if (!isNumber(instance)) return;
  let failed, cmp;
  if (schema.get('exclusiveMinimum') === true) {
    failed = numCompare(instance, v) <= 0;
    cmp = 'less than or equal to';
  } else {
    failed = numCompare(instance, v) < 0;
    cmp = 'less than';
  }
  if (failed) {
    yield err(`${reprValue(instance)} is ${cmp} the minimum of ${numToStr(v)}`, 'minimum', path);
  }
}

export function* maximumDraft4(v, instance, schema, path, api) {
  if (!isNumber(instance)) return;
  let failed, cmp;
  if (schema.get('exclusiveMaximum') === true) {
    failed = numCompare(instance, v) >= 0;
    cmp = 'greater than or equal to';
  } else {
    failed = numCompare(instance, v) > 0;
    cmp = 'greater than';
  }
  if (failed) {
    yield err(`${reprValue(instance)} is ${cmp} the maximum of ${numToStr(v)}`, 'maximum', path);
  }
}

export function* multipleOf(v, instance, schema, path, api) {
  if (!isNumber(instance)) return;
  let failed;
  if (typeof v === 'number') {
    const q = (typeof instance === 'bigint' ? Number(instance) : instance) / v;
    failed = !Number.isFinite(q) || Math.trunc(q) !== q;
  } else if (typeof instance === 'bigint') {
    failed = instance % v !== 0n;
  } else {
    failed = instance % Number(v) !== 0;
  }
  if (failed) {
    yield err(`${reprValue(instance)} is not a multiple of ${numToStr(v)}`, 'multipleOf', path);
  }
}

// ---------- array ----------

export function* minItems(v, instance, schema, path, api) {
  if (!Array.isArray(instance)) return;
  if (numCompare(instance.length, v) < 0) {
    const message = numCompare(v, 1n) === 0
      ? `${reprValue(instance)} should be non-empty`
      : `${reprValue(instance)} is too short`;
    yield err(message, 'minItems', path);
  }
}

export function* maxItems(v, instance, schema, path, api) {
  if (!Array.isArray(instance)) return;
  if (numCompare(instance.length, v) > 0) {
    yield err(`${reprValue(instance)} is too long`, 'maxItems', path);
  }
}

export function* uniqueItems(v, instance, schema, path, api) {
  if (v !== true || !Array.isArray(instance)) return;
  outer: for (let i = 0; i < instance.length; i++) {
    for (let j = i + 1; j < instance.length; j++) {
      if (pyEqual(instance[i], instance[j])) {
        yield err(`${reprValue(instance)} has non-unique elements`, 'uniqueItems', path);
        break outer;
      }
    }
  }
}

// draft 2020-12: "items" applies to everything after "prefixItems"
export function* items2020(v, instance, schema, path, api) {
  if (!Array.isArray(instance)) return;
  const prefixItems = schema.get('prefixItems');
  const prefixLen = Array.isArray(prefixItems) ? prefixItems.length : 0;
  const total = instance.length;
  const extra = total - prefixLen;
  if (extra <= 0) return;

  if (v === false) {
    const rest = instance.slice(prefixLen);
    yield err(
      `Expected at most ${prefixLen} item${prefixLen !== 1 ? 's' : ''} but found ${extra} extra: ${reprValue(rest)}`,
      'items', path,
    );
    return;
  }
  if (v === true) return;
  for (let i = prefixLen; i < total; i++) {
    yield* api.descend(instance[i], v, path, [i]);
  }
}

export function* prefixItems(v, instance, schema, path, api) {
  if (!Array.isArray(instance)) return;
  for (let i = 0; i < v.length && i < instance.length; i++) {
    yield* api.descend(instance[i], v[i], path, [i]);
  }
}

// drafts up to 2019-09: "items" is either a schema (all elements) or a
// list (tuple validation, rest handled by "additionalItems")
export function* itemsLegacy(v, instance, schema, path, api) {
  if (!Array.isArray(instance)) return;
  if (Array.isArray(v)) {
    for (let i = 0; i < v.length && i < instance.length; i++) {
      yield* api.descend(instance[i], v[i], path, [i]);
    }
  } else {
    for (let i = 0; i < instance.length; i++) {
      yield* api.descend(instance[i], v, path, [i]);
    }
  }
}

export function* additionalItems(v, instance, schema, path, api) {
  if (!Array.isArray(instance)) return;
  const items = schema.get('items');
  if (!Array.isArray(items)) return;
  const lenItems = items.length;
  if (v instanceof Map) {
    for (let i = lenItems; i < instance.length; i++) {
      yield* api.descend(instance[i], v, path, [i]);
    }
  } else if (v === false && instance.length > lenItems) {
    const [joined, verb] = extrasMsg(instance.slice(lenItems));
    yield err(`Additional items are not allowed (${joined} ${verb} unexpected)`, 'additionalItems', path);
  }
}

export function* contains(v, instance, schema, path, api) {
  if (!Array.isArray(instance)) return;
  let matches = 0;
  const minContains = schema.has('minContains') ? schema.get('minContains') : 1n;
  const maxContains = schema.has('maxContains') ? schema.get('maxContains') : BigInt(instance.length);

  for (const each of instance) {
    if (api.isValid(v, each)) {
      matches++;
      if (numCompare(matches, maxContains) > 0) {
        yield err(
          `Too many items match the given schema (expected at most ${numToStr(maxContains)})`,
          'contains', path,
        );
        return;
      }
    }
  }
  if (numCompare(matches, minContains) < 0) {
    let message = `${reprValue(instance)} does not contain items matching the given schema`;
    if (numCompare(minContains, 1n) > 0 && matches > 0) {
      message = `Too few items match the given schema (expected at least ${numToStr(minContains)} but only ${matches} matched)`;
    }
    yield err(message, 'contains', path);
  }
}

export function* noop() {}

// ---------- applicators ----------

export function* allOf(v, instance, schema, path, api) {
  for (let i = 0; i < v.length; i++) {
    yield* api.descend(instance, v[i], path, []);
  }
}

export function* anyOf(v, instance, schema, path, api) {
  const allErrors = [];
  for (const subschema of v) {
    const errs = [...api.descend(instance, subschema, path, [])];
    if (!errs.length) return;
    allErrors.push(...errs);
  }
  yield err(
    `${reprValue(instance)} is not valid under any of the given schemas`,
    'anyOf', path, allErrors,
  );
}

export function* oneOf(v, instance, schema, path, api) {
  const allErrors = [];
  let firstValid = null;
  let firstIndex = -1;
  for (let i = 0; i < v.length; i++) {
    const errs = [...api.descend(instance, v[i], path, [])];
    if (!errs.length) { firstValid = v[i]; firstIndex = i; break; }
    allErrors.push(...errs);
  }
  if (firstIndex === -1) {
    yield err(
      `${reprValue(instance)} is not valid under any of the given schemas`,
      'oneOf', path, allErrors,
    );
    return;
  }
  const moreValid = [];
  for (let i = firstIndex + 1; i < v.length; i++) {
    if (api.isValid(v[i], instance)) moreValid.push(v[i]);
  }
  if (moreValid.length) {
    moreValid.push(firstValid);
    yield err(
      `${reprValue(instance)} is valid under each of ${moreValid.map(reprValue).join(', ')}`,
      'oneOf', path, allErrors,
    );
  }
}

export function* not_(v, instance, schema, path, api) {
  if (api.isValid(v, instance)) {
    yield err(`${reprValue(instance)} should not be valid under ${reprValue(v)}`, 'not', path);
  }
}

export function* if_(v, instance, schema, path, api) {
  if (api.isValid(v, instance)) {
    if (schema.has('then')) {
      yield* api.descend(instance, schema.get('then'), path, []);
    }
  } else {
    if (schema.has('else')) {
      yield* api.descend(instance, schema.get('else'), path, []);
    }
  }
}

export function* ref(v, instance, schema, path, api) {
  const resolved = api.resolveRef(v);
  yield* api.descend(instance, resolved, path, []);
}

// ---------- unevaluated* (2019-09 / 2020-12) ----------

export function* unevaluatedItems(v, instance, schema, path, api) {
  if (!Array.isArray(instance)) return;
  const evaluated = api.findEvaluatedItemIndexes(instance, schema);
  const unevaluated = [];
  for (let i = 0; i < instance.length; i++) {
    if (!evaluated.has(i)) unevaluated.push([i, instance[i]]);
  }
  if (!unevaluated.length) return;
  if (v === false) {
    const [joined, verb] = extrasMsg(unevaluated.map(([, item]) => item));
    yield err(`Unevaluated items are not allowed (${joined} ${verb} unexpected)`, 'unevaluatedItems', path);
  } else if (v instanceof Map) {
    for (const [index, item] of unevaluated) {
      yield* api.descend(item, v, path, [index]);
    }
  }
}

export function* unevaluatedProperties(v, instance, schema, path, api) {
  if (!(instance instanceof Map)) return;
  const evaluated = api.findEvaluatedPropertyKeys(instance, schema);
  const extras = [...instance.keys()].filter((k) => !evaluated.has(k));
  if (!extras.length) return;
  if (v instanceof Map) {
    for (const k of [...extras].sort()) {
      yield* api.descend(instance.get(k), v, path, [k]);
    }
  } else if (v === false) {
    const sorted = [...extras].sort();
    const [joined, verb] = extrasMsg(sorted);
    yield err(`Unevaluated properties are not allowed (${joined} ${verb} unexpected)`, 'unevaluatedProperties', path);
  }
}

// Core validator: draft detection, error iteration in schema-keyword order,
// $ref resolution, check_schema emulation, and best_match error selection --
// mirroring Python's jsonschema.validate() behavior.

import { reprValue } from './pyrepr.mjs';
import * as kw from './keywords.mjs';

export class SchemaProblem extends Error {
  constructor(instanceRepr, schemaPath) {
    super(instanceRepr);
    this.instanceRepr = instanceRepr; // repr of the offending schema fragment
    this.schemaPath = schemaPath;     // e.g. "['properties']['a']['type']"
  }
}

export class RegexProblem extends Error {
  constructor(pattern) {
    super(pattern);
    this.pattern = pattern;
  }
}

export class TypeProblem extends Error {
  constructor(pyType) {
    super(pyType);
    this.pyType = pyType;
  }
}

export class RefProblem extends Error {}

const VALID_TYPES = new Set(['array', 'boolean', 'integer', 'null', 'number', 'object', 'string']);
const WEAK_MATCHES = new Set(['anyOf', 'oneOf']);

// ---------- keyword maps per draft ----------

const COMMON = {
  type: kw.type,
  properties: kw.properties,
  patternProperties: kw.patternProperties,
  additionalProperties: kw.additionalProperties,
  required: kw.required,
  minProperties: kw.minProperties,
  maxProperties: kw.maxProperties,
  minLength: kw.minLength,
  maxLength: kw.maxLength,
  pattern: kw.pattern,
  multipleOf: kw.multipleOf,
  minItems: kw.minItems,
  maxItems: kw.maxItems,
  uniqueItems: kw.uniqueItems,
  allOf: kw.allOf,
  anyOf: kw.anyOf,
  oneOf: kw.oneOf,
  not: kw.not_,
  enum: kw.enum_,
};

const DRAFT4 = {
  ...COMMON,
  items: kw.itemsLegacy,
  additionalItems: kw.additionalItems,
  minimum: kw.minimumDraft4,
  maximum: kw.maximumDraft4,
  dependencies: kw.dependencies,
};

const DRAFT6 = {
  ...COMMON,
  items: kw.itemsLegacy,
  additionalItems: kw.additionalItems,
  minimum: kw.minimum,
  maximum: kw.maximum,
  exclusiveMinimum: kw.exclusiveMinimum,
  exclusiveMaximum: kw.exclusiveMaximum,
  dependencies: kw.dependencies,
  contains: kw.contains,
  const: kw.const_,
  propertyNames: kw.propertyNames,
};

const DRAFT7 = {
  ...DRAFT6,
  if: kw.if_,
};

const DRAFT2019 = {
  ...DRAFT7,
  items: kw.itemsLegacy,
  additionalItems: kw.additionalItems,
  dependentRequired: kw.dependentRequired,
  dependentSchemas: kw.dependentSchemas,
  minContains: kw.noop,
  maxContains: kw.noop,
  unevaluatedItems: kw.unevaluatedItems,
  unevaluatedProperties: kw.unevaluatedProperties,
  $ref: kw.ref,
};

const DRAFT2020 = {
  ...DRAFT2019,
  items: kw.items2020,
  prefixItems: kw.prefixItems,
  additionalItems: undefined, // not a 2020-12 keyword
};

function detectDraft(schema) {
  if (schema instanceof Map) {
    const s = schema.get('$schema');
    if (typeof s === 'string') {
      if (s.includes('draft-04')) return 'draft4';
      if (s.includes('draft-06')) return 'draft6';
      if (s.includes('draft-07')) return 'draft7';
      if (s.includes('2019-09')) return 'draft2019';
    }
  }
  return 'draft2020';
}

const VALIDATOR_SETS = {
  draft4: DRAFT4,
  draft6: DRAFT6,
  draft7: DRAFT7,
  draft2019: DRAFT2019,
  draft2020: DRAFT2020,
};

// ---------- context ----------

function makeContext(rootSchema) {
  const draft = detectDraft(rootSchema);
  const regexCache = new Map();
  const ctx = {
    draft,
    root: rootSchema,
    validators: VALIDATOR_SETS[draft],
    legacyRef: draft === 'draft4' || draft === 'draft6' || draft === 'draft7',
  };

  const api = {
    *descend(instance, subschema, path, subPath) {
      yield* iterErrors(ctx, api, instance, subschema, path.concat(subPath));
    },
    isValid(subschema, instance) {
      return iterErrors(ctx, api, instance, subschema, []).next().done;
    },
    getRegex(pattern) {
      if (!regexCache.has(pattern)) regexCache.set(pattern, new RegExp(pattern));
      return regexCache.get(pattern);
    },
    resolveRef(ref) {
      return resolveRef(ctx, ref);
    },
    findEvaluatedPropertyKeys(instance, schema) {
      return findEvaluatedPropertyKeys(ctx, api, instance, schema);
    },
    findEvaluatedItemIndexes(instance, schema) {
      return findEvaluatedItemIndexes(ctx, api, instance, schema);
    },
  };
  ctx.api = api;
  return ctx;
}

// ---------- $ref resolution (local JSON pointers) ----------

function resolveRef(ctx, ref) {
  if (typeof ref !== 'string' || !ref.startsWith('#')) {
    throw new RefProblem(`unknown or unsupported reference: ${reprValue(ref)}`);
  }
  const fragment = decodeURIComponent(ref.slice(1));
  if (fragment === '') return ctx.root;
  if (!fragment.startsWith('/')) {
    throw new RefProblem(`Unresolvable JSON pointer: ${reprValue(fragment)}`);
  }
  let current = ctx.root;
  for (const raw of fragment.slice(1).split('/')) {
    const part = raw.replace(/~1/g, '/').replace(/~0/g, '~');
    if (current instanceof Map) {
      if (!current.has(part)) throw new RefProblem(`Unresolvable JSON pointer: ${reprValue(fragment)}`);
      current = current.get(part);
    } else if (Array.isArray(current)) {
      if (!/^(0|[1-9]\d*)$/.test(part)) throw new RefProblem(`Unresolvable JSON pointer: ${reprValue(fragment)}`);
      const index = Number(part);
      if (index >= current.length) throw new RefProblem(`Unresolvable JSON pointer: ${reprValue(fragment)}`);
      current = current[index];
    } else {
      throw new RefProblem(`Unresolvable JSON pointer: ${reprValue(fragment)}`);
    }
  }
  return current;
}

// ---------- error iteration ----------

function* iterErrors(ctx, api, instance, schema, path) {
  if (schema === true) return;
  if (schema === false) {
    yield {
      message: `False schema does not allow ${reprValue(instance)}`,
      validator: 'false',
      path,
      context: [],
    };
    return;
  }
  if (!(schema instanceof Map)) return;

  // pre-2019 drafts: $ref replaces all sibling keywords
  if (ctx.legacyRef && schema.has('$ref')) {
    const resolved = resolveRef(ctx, schema.get('$ref'));
    yield* iterErrors(ctx, api, instance, resolved, path);
    return;
  }

  for (const [keyword, value] of schema) {
    const validator = ctx.validators[keyword];
    if (validator === undefined) continue;
    yield* validator(value, instance, schema, path, api);
  }
}

// ---------- best_match (as observed: max by relevance, first wins ties,
//    no descent into context) ----------

function relevance(error) {
  return [-error.path.length, WEAK_MATCHES.has(error.validator) ? 0 : 1];
}

function cmpRelevance(a, b) {
  const ra = relevance(a);
  const rb = relevance(b);
  for (let i = 0; i < ra.length; i++) {
    if (ra[i] !== rb[i]) return ra[i] - rb[i];
  }
  return 0;
}

export function bestMatch(errors) {
  if (!errors.length) return null;
  let best = errors[0];
  for (let i = 1; i < errors.length; i++) {
    if (cmpRelevance(errors[i], best) > 0) best = errors[i];
  }
  return best;
}

// ---------- evaluated-items / evaluated-properties tracking ----------

function forEachRefChain(ctx, schema, fn) {
  const seen = new Set();
  let current = schema;
  while (current instanceof Map) {
    const ref = current.get('$ref');
    if (typeof ref !== 'string' || seen.has(ref)) return;
    seen.add(ref);
    let resolved;
    try {
      resolved = resolveRef(ctx, ref);
    } catch {
      return;
    }
    if (!(resolved instanceof Map)) return;
    fn(resolved);
    current = resolved;
  }
}

function findEvaluatedPropertyKeys(ctx, api, instance, schema) {
  const evaluated = new Set();
  if (!(instance instanceof Map) || !(schema instanceof Map)) return evaluated;

  forEachRefChain(ctx, schema, (resolved) => {
    for (const k of findEvaluatedPropertyKeys(ctx, api, instance, resolved)) evaluated.add(k);
  });

  const props = schema.get('properties');
  if (props instanceof Map) {
    for (const p of props.keys()) if (instance.has(p)) evaluated.add(p);
  }
  const pp = schema.get('patternProperties');
  if (pp instanceof Map) {
    const regexes = [...pp.keys()].map((p) => api.getRegex(p));
    for (const k of instance.keys()) {
      if (regexes.some((r) => r.test(k))) evaluated.add(k);
    }
  }
  if (schema.has('additionalProperties') && schema.get('additionalProperties') !== false) {
    const regexes = pp instanceof Map ? [...pp.keys()].map((p) => api.getRegex(p)) : [];
    for (const k of instance.keys()) {
      const inProps = props instanceof Map && props.has(k);
      const inPatterns = regexes.some((r) => r.test(k));
      if (!inProps && !inPatterns) evaluated.add(k);
    }
  }

  for (const keyword of ['allOf', 'anyOf', 'oneOf']) {
    const subs = schema.get(keyword);
    if (Array.isArray(subs)) {
      for (const sub of subs) {
        if (api.isValid(sub, instance)) {
          for (const k of findEvaluatedPropertyKeys(ctx, api, instance, sub)) evaluated.add(k);
        }
      }
    }
  }
  if (schema.has('if')) {
    if (api.isValid(schema.get('if'), instance)) {
      if (schema.has('then')) {
        for (const k of findEvaluatedPropertyKeys(ctx, api, instance, schema.get('then'))) evaluated.add(k);
      }
    } else if (schema.has('else')) {
      for (const k of findEvaluatedPropertyKeys(ctx, api, instance, schema.get('else'))) evaluated.add(k);
    }
  }
  return evaluated;
}

function findEvaluatedItemIndexes(ctx, api, instance, schema) {
  const evaluated = new Set();
  if (!Array.isArray(instance) || !(schema instanceof Map)) return evaluated;

  forEachRefChain(ctx, schema, (resolved) => {
    for (const i of findEvaluatedItemIndexes(ctx, api, instance, resolved)) evaluated.add(i);
  });

  const prefixItems = schema.get('prefixItems');
  if (Array.isArray(prefixItems)) {
    const n = Math.min(prefixItems.length, instance.length);
    for (let i = 0; i < n; i++) evaluated.add(i);
  }
  if (schema.has('items') && schema.get('items') !== false) {
    const start = Array.isArray(prefixItems) ? prefixItems.length : 0;
    for (let i = start; i < instance.length; i++) evaluated.add(i);
  }
  if (schema.has('contains')) {
    const containsSchema = schema.get('contains');
    for (let i = 0; i < instance.length; i++) {
      if (api.isValid(containsSchema, instance[i])) evaluated.add(i);
    }
  }

  for (const keyword of ['allOf', 'anyOf', 'oneOf']) {
    const subs = schema.get(keyword);
    if (Array.isArray(subs)) {
      for (const sub of subs) {
        if (api.isValid(sub, instance)) {
          for (const i of findEvaluatedItemIndexes(ctx, api, instance, sub)) evaluated.add(i);
        }
      }
    }
  }
  if (schema.has('if')) {
    if (api.isValid(schema.get('if'), instance)) {
      if (schema.has('then')) {
        for (const i of findEvaluatedItemIndexes(ctx, api, instance, schema.get('then'))) evaluated.add(i);
      }
    } else if (schema.has('else')) {
      for (const i of findEvaluatedItemIndexes(ctx, api, instance, schema.get('else'))) evaluated.add(i);
    }
  }
  return evaluated;
}

// ---------- check_schema (minimal emulation) ----------

const SUBSCHEMA_KEYS = [
  'additionalProperties', 'additionalItems', 'items', 'contains',
  'propertyNames', 'not', 'if', 'then', 'else',
  'unevaluatedItems', 'unevaluatedProperties',
];
const SUBSCHEMA_MAP_KEYS = ['properties', 'patternProperties', 'dependentSchemas', '$defs', 'definitions'];
const SUBSCHEMA_LIST_KEYS = ['allOf', 'anyOf', 'oneOf', 'prefixItems'];

function checkSchemaNode(node, path) {
  if (node === true || node === false) return;
  if (!(node instanceof Map)) {
    throw new SchemaProblem(reprValue(node), path);
  }
  if (node.has('type')) {
    const t = node.get('type');
    if (typeof t === 'string') {
      if (!VALID_TYPES.has(t)) throw new SchemaProblem(reprStr(t), path + "['type']");
    } else if (Array.isArray(t)) {
      const seen = new Set();
      for (const each of t) {
        if (typeof each !== 'string' || !VALID_TYPES.has(each) || seen.has(each) || !t.length) {
          throw new SchemaProblem(reprValue(t), path + "['type']");
        }
        seen.add(each);
      }
      if (!t.length) throw new SchemaProblem(reprValue(t), path + "['type']");
    } else {
      throw new SchemaProblem(reprValue(t), path + "['type']");
    }
  }
  if (node.has('pattern') && typeof node.get('pattern') === 'string') {
    assertCompiles(node.get('pattern'));
  }
  const pp = node.get('patternProperties');
  if (pp instanceof Map) {
    for (const p of pp.keys()) assertCompiles(p);
  }

  for (const key of SUBSCHEMA_KEYS) {
    const v = node.get(key);
    if (v instanceof Map) checkSchemaNode(v, path + `['${key}']`);
    else if (Array.isArray(v)) v.forEach((e, i) => { if (e instanceof Map) checkSchemaNode(e, path + `['${key}'][${i}]`); });
  }
  for (const key of SUBSCHEMA_MAP_KEYS) {
    const v = node.get(key);
    if (v instanceof Map) {
      for (const [k2, sub] of v) {
        if (sub instanceof Map) checkSchemaNode(sub, path + `['${key}'][${reprStr(k2)}]`);
      }
    }
  }
  for (const key of SUBSCHEMA_LIST_KEYS) {
    const v = node.get(key);
    if (Array.isArray(v)) v.forEach((e, i) => { if (e instanceof Map) checkSchemaNode(e, path + `['${key}'][${i}]`); });
  }
  const deps = node.get('dependencies');
  if (deps instanceof Map) {
    for (const [k2, sub] of deps) {
      if (sub instanceof Map) checkSchemaNode(sub, path + `['dependencies'][${reprStr(k2)}]`);
    }
  }
}

function assertCompiles(pattern) {
  try {
    new RegExp(pattern);
  } catch {
    throw new RegexProblem(pattern);
  }
}

import { reprStr } from './pyrepr.mjs';

// ---------- entry point ----------

export function runValidate(instance, schema) {
  // validator_for() behavior for non-object schemas
  if (schema !== true && schema !== false && !(schema instanceof Map)) {
    if (schema === null) throw new TypeProblem('NoneType');
    if (typeof schema === 'bigint') throw new TypeProblem('int');
    if (typeof schema === 'number') throw new TypeProblem('float');
    if (Array.isArray(schema)) throw new TypeProblem('list');
    if (typeof schema === 'string') {
      // "$schema" in <str> is legal Python; validation then fails on the
      // metaschema because the schema is not an object
      throw new SchemaProblem(reprStr(schema), '');
    }
    throw new TypeProblem('object');
  }
  checkSchemaNode(schema, '');
  const ctx = makeContext(schema);
  const errors = [...iterErrors(ctx, ctx.api, instance, schema, [])];
  return bestMatch(errors);
}

