// Best-effort reproduction of the PyInstaller binary's crash output for the
// non-ValidationError paths (stderr, exit code 1). The PYI- prefix carries a
// process id in the original binary, so it can never match byte-for-byte.

const PYI = () => `[PYI-${process.pid}:ERROR] Failed to execute script 'test2' due to unhandled exception!`;

export function printJsonDecodeTraceback(error, lineNo) {
  const frames = [
    'Traceback (most recent call last):',
    `  File "test2.py", line ${lineNo}, in <module>`,
    '  File "json/__init__.py", line 346, in loads',
    '  File "json/decoder.py", line 337, in decode',
  ];
  if (error.msg !== 'Extra data') {
    frames.push('  File "json/decoder.py", line 355, in raw_decode');
  }
  frames.push(`json.decoder.JSONDecodeError: ${error.message}`);
  frames.push(PYI());
  process.stderr.write(frames.join('\n') + '\n');
}

// Exact shape observed for an invalid simple "type" string under draft 2020-12.
const TYPE_METASCHEMA_FRAGMENT = [
  "    {'anyOf': [{'$ref': '#/$defs/simpleTypes'},",
  "               {'type': 'array',",
  "                'items': {'$ref': '#/$defs/simpleTypes'},",
  "                'minItems': 1,",
  "                'uniqueItems': True}]}",
].join('\n');

export function printSchemaErrorTraceback(problem) {
  const lines = [
    'Traceback (most recent call last):',
    '  File "test2.py", line 15, in <module>',
    `jsonschema.exceptions.SchemaError: ${problem.instanceRepr} is not valid under any of the given schemas`,
    '',
    `Failed validating 'anyOf' in metaschema['allOf'][3]['properties']['type']:`,
    TYPE_METASCHEMA_FRAGMENT,
    '',
    `On schema${problem.schemaPath}:`,
    `    ${problem.instanceRepr}`,
    PYI(),
  ];
  process.stderr.write(lines.join('\n') + '\n');
}

export function printRegexTraceback(problem) {
  const lines = [
    'Traceback (most recent call last):',
    '  File "test2.py", line 15, in <module>',
    '  File "jsonschema/_format.py", line 140, in check',
    '  File "jsonschema/_format.py", line 392, in is_regex',
    '  File "re/__init__.py", line 228, in compile',
    '  File "re/__init__.py", line 307, in _compile',
    `re.error: invalid regular expression ${problem.pattern}`,
    PYI(),
  ];
  process.stderr.write(lines.join('\n') + '\n');
}

export function printTypeErrorTraceback(problem) {
  const lines = [
    'Traceback (most recent call last):',
    '  File "test2.py", line 15, in <module>',
    '  File "jsonschema/validators.py", line 1326, in validate',
    '  File "jsonschema/validators.py", line 1398, in validator_for',
    `TypeError: argument of type '${problem.pyType}' is not iterable`,
