// argparse emulation for:
//   parser.add_argument('--a', type=str, required=True, help='instance data (JSON string)')
//   parser.add_argument('--b', type=str, required=True, help='schema (JSON string)')
// prog name matches the reference executable's output.

const PROG = 'test2_executable';
const USAGE = `usage: ${PROG} [-h] --a A --b B`;
const HELP = [
  USAGE,
  '',
  'options:',
  '  -h, --help  show this help message and exit',
  '  --a A       instance data (JSON string)',
  '  --b B       schema (JSON string)',
].join('\n');

const LONG_OPTIONS = { '--help': 'help', '--a': 'a', '--b': 'b' };

function errorExit(message) {
  process.stderr.write(`${USAGE}\n${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelpExit() {
  process.stdout.write(HELP + '\n');
  process.exit(0);
}

// argparse's _negative_number_matcher
function isNegativeNumber(token) {
  return /^-\d+$/.test(token) || /^-\d*\.\d+$/.test(token);
}

// Whether argparse would treat this token as an option string rather than a value.
function looksLikeOption(token) {
  return (
    token.length > 1 &&
    token[0] === '-' &&
    !isNegativeNumber(token) &&
    !token.includes(' ')
  );
}

export function parseArgs(argv) {
  const values = { a: undefined, b: undefined };
  const seen = new Set();
  const extras = [];
  let noMoreOptions = false;
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    if (noMoreOptions) {
      extras.push(token);
      i++;
      continue;
    }
    if (token === '--') {
      noMoreOptions = true;
      i++;
      continue;
    }

    if (token.startsWith('--')) {
      let name = token;
      let inline;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        inline = token.slice(eq + 1);
      }

      let match = Object.prototype.hasOwnProperty.call(LONG_OPTIONS, name) ? name : null;
      if (match === null) {
        const candidates = Object.keys(LONG_OPTIONS).filter((o) => o.startsWith(name));
        if (candidates.length === 1) {
          match = candidates[0];
        } else if (candidates.length > 1) {
          errorExit(`ambiguous option: ${name} could match ${candidates.join(', ')}`);
        } else {
          extras.push(token); // unrecognized optional
          i++;
          continue;
        }
      }

      const dest = LONG_OPTIONS[match];
      if (dest === 'help') printHelpExit();

      if (inline !== undefined) {
        values[dest] = inline;
        seen.add(dest);
        i++;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        errorExit(`argument ${match}: expected one argument`);
      }
      values[dest] = next;
      seen.add(dest);
      i += 2;
      continue;
    }

    if (token === '-h') printHelpExit();

    if (looksLikeOption(token)) {
      extras.push(token); // unrecognized short option
      i++;
      continue;
    }

    extras.push(token); // positional (this parser defines none)
    i++;
  }

  const missing = [];
  if (!seen.has('a')) missing.push('--a');
  if (!seen.has('b')) missing.push('--b');
  if (missing.length) {
    errorExit(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length) {
    errorExit(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return values;
}

// Entry point — mirrors /workspace/dataset/jsonschema/test2.py:
//   parse --a (instance JSON) and --b (schema JSON), then jsonschema.validate,
//   printing "valid" or the best-match ValidationError message.

import { parseArgs } from './lib/argparse.mjs';
import { jsonLoads, JSONDecodeError } from './lib/pyjson.mjs';
import {
  runValidate,
  SchemaProblem,
  RegexProblem,
  TypeProblem,
  RefProblem,
} from './lib/validator.mjs';
import {
  printJsonDecodeTraceback,
  printSchemaErrorTraceback,
  printRegexTraceback,
  printTypeErrorTraceback,
  printRefTraceback,
  printRecursionTraceback,
} from './lib/tracebacks.mjs';

function loadJson(text, lineNo) {
  try {
    return jsonLoads(text);
  } catch (e) {
    if (e instanceof JSONDecodeError) {
      printJsonDecodeTraceback(e, lineNo);
      process.exit(1);
    }
    throw e;
  }
}

const args = parseArgs(process.argv.slice(2));

const instance = loadJson(args.a, 11);
const schema = loadJson(args.b, 12);

try {
  const best = runValidate(instance, schema);
  if (best === null) {
    console.log('valid');
  } else {
    console.log(best.message);
  }
} catch (e) {
  if (e instanceof SchemaProblem) {
    printSchemaErrorTraceback(e);
    process.exit(1);
  }
  if (e instanceof RegexProblem) {
    printRegexTraceback(e);
    process.exit(1);
  }
  if (e instanceof TypeProblem) {
    printTypeErrorTraceback(e);
    process.exit(1);
  }
  if (e instanceof RefProblem) {
    printRefTraceback(e);
    process.exit(1);
  }
  if (e instanceof RangeError) {
    // infinite $ref recursion, as the original hits RecursionError
    printRecursionTraceback();
    process.exit(1);
  }
  throw e;
}
